+	cwd: string,
+	args: string[],
+	options: {
+		env?: Partial<NodeJS.ProcessEnv>;
+		timeout?: number;
+		input?: string;
+		hooksPath?: string;
+	} = {},
+) {
+	try {
+		return await new Promise<string>((resolve, reject) => {
+			const child = execFile(
+				"git",
+				options.hooksPath
+					? ["-c", `core.hooksPath=${options.hooksPath}`, ...args]
